L9_1.m_Pos = "C"
L9_1.m_Talk_KOREA = "거기다가 탈출 루트에서 만난 제 3종 침식체까지 격파하셨군요."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "脱出ルートで遭遇した第3種侵食体まで撃破しましたね。"
L9_1.m_Talk_ENG = "You even destroyed the Category 3 C.O. on your way out."
L9_1.m_Talk_TWN = "並且各位在撤離途中，還擊敗了遭遇的3級侵蝕體。"
L9_1.m_Talk_THA = "แถมพวกคุณยังทำลายวัตถุคอร์รัปต์คลาส 3 ระหว่างที่หนีออกมาด้วย"
L9_1.m_Talk_VTN = "Các bạn thậm chí còn tiêu diệt được V.T.B.A.M. Loại 3 trên đường thoát cơ mà."
L9_1.m_Talk_SCN = "并且各位在撤离途中，还击败了遭遇的3级侵蚀体。"
L9_1.m_Talk_DEU = "Ihr habt auf dem Rückweg sogar das C. O. der Kategorie 3 zerstört."
L9_1.m_Talk_FRA = "Vous avez même détruit l'O.C. de catégorie 3 en passant."
L10_1 = {}
L10_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE4_END@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 14
L10_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L10_1.m_Pos = "C"
L10_1.m_Talk_KOREA = "덕분에 조금 전, 관리국 행정실로부터 감사패까지 도착했습니다."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "おかげさまで、先ほど管理局行政室から感謝トロフィーが届きました。"
L10_1.m_Talk_ENG = "Thanks to you, the Administration sent us a plaque of appreciation just now."
L10_1.m_Talk_TWN = "不久前管理局行政室送來了感謝狀，這都是各位的功勞。"
L10_1.m_Talk_THA = "องค์การบริหารโลกชื่นชมผลงานครั้งนี้มาก ก็เลยส่งป้ายประกาศเกียรติคุณมาให้เมื่อกี้นี้เอง"
L10_1.m_Talk_VTN = "Nhờ các bạn, Cục Quản Lý đã trao giấy khen vinh danh cho chúng ta đấy."
L10_1.m_Talk_SCN = "不久前管理局行政部送来了感谢状，这都是各位的功劳呀。"
L10_1.m_Talk_DEU = "Dank euch hat uns die Administration soeben eine Anerkennungsplakette geschickt."
L10_1.m_Talk_FRA = "Grâce à vous, l'Administration vient tout juste de nous faire parvenir une plaque de remerciement."
L11_1 = {}
L11_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE4_END@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 14
L11_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L11_1.m_Pos = "C"
L11_1.m_Talk_KOREA = "살다 보니 이런 날이 또 오네요."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "こんな日が来るなんて、思いもよりませんでした。"
L11_1.m_Talk_ENG = "What a crazy day."
L11_1.m_Talk_TWN = "沒想到在我活著的時候能見到這一天。"
L11_1.m_Talk_THA = "ช่างเป็นวันที่วุ่นวายสุดๆ ไปเลย"
L11_1.m_Talk_VTN = "Thật là một ngày điên rồ."
L11_1.m_Talk_SCN = "没想到在我有生之年能见到这一天。"
L11_1.m_Talk_DEU = "Was für ein verrückter Tag!"
L11_1.m_Talk_FRA = "Quelle folle journée !"
L12_1 = {}
L12_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE4_END@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 14
L12_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L12_1.m_Pos = "C"
L12_1.m_Talk_KOREA = "공백기간이 꽤 길어서 걱정을 좀 했었는데......."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "ブランク期間が長いのが気がかりでしたが……"
L12_1.m_Talk_ENG = "I was a bit worried that you'd be rusty by now..."
L12_1.m_Talk_TWN = "師父這麼久沒有參加小隊作戰，本來我還很擔心呢。"
L12_1.m_Talk_THA = "ตอนแรกฉันก็กังวลอยู่นิดหน่อย ว่าคุณคงจะฝีมือตกแล้ว..."
L12_1.m_Talk_VTN = "Tôi cứ lo là người đã bị lụt nghề rồi ấy chứ..."
L12_1.m_Talk_SCN = "老师这么久没有参加小队作战，本来我还挺担心的，"
L12_1.m_Talk_DEU = "Ich hatte mir ein wenig Sorgen gemacht, du wärst eingerostet …"
L12_1.m_Talk_FRA = "Je craignais que vous ne soyez un peu rouillés..."
L13_1 = {}
L13_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE4_END@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 14
L13_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L13_1.m_bWaitClick = true
