L13_1.m_Pos = "C"
L13_1.m_Talk_KOREA = "역시 기본 실력이 어딜 가진 않는군요."
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "やはり腕が衰えることはなかったですね。"
L13_1.m_Talk_ENG = "But it looks like you still got game."
L13_1.m_Talk_TWN = "但果然師父的實力還在。"
L13_1.m_Talk_THA = "แต่ดูเหมือนว่ายังไม่ทิ้งลายเดิมเลยนะคะ"
L13_1.m_Talk_VTN = "Nhưng có vẻ như người vẫn duy trì được phong độ."
L13_1.m_Talk_SCN = "但果然老师的实力不容小觑。"
L13_1.m_Talk_DEU = "Aber du hast es offenbar immer noch drauf."
L13_1.m_Talk_FRA = "Mais vous savez toujours vous y prendre, semble-t-il."
