L18_1 = {}
L18_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE4_END@18#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 14
L18_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L18_1.m_Pos = "R"
L18_1.m_Talk_KOREA = "할말은 많지만 일단 제일 중요한 것부터 짚고 넘어가지."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "言いたいことは山々だが、一番大事なことから聞こう。"
L18_1.m_Talk_ENG = "I have a lot to say, but I'll start with the most important thing."
L18_1.m_Talk_TWN = "雖然我有很多話要說，總之先從最重要的開始吧。"
L18_1.m_Talk_THA = "ฉันมีเรื่องอยากคุยกับเธอเยอะแยะเลย แต่ขอเริ่มจากเรื่องสำคัญที่สุดก่อนเลย"
L18_1.m_Talk_VTN = "Ta muốn nói rất nhiều điều, nhưng ta sẽ bắt đầu với điều quan trọng nhất."
L18_1.m_Talk_SCN = "虽然有一大堆要说的话，总之先从最重要的开始吧。"
L18_1.m_Talk_DEU = "Ich habe eine Menge zu sagen, aber ich beginne mit dem Wichtigsten."
L18_1.m_Talk_FRA = "J'ai beaucoup de choses à dire, mais je vais commencer par la plus importante."
L19_1 = {}
L19_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE4_END@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 14
L19_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L19_1.m_Pos = "L"
L19_1.m_Talk_KOREA = "짧게 해 주시면 좋겠군요. 밀린 서류가 많아서."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "手短にお願いしますね。確認する書類が溜まっているので。"
L19_1.m_Talk_ENG = "Can we make it quick? I have a lot of paperwork to do."
L19_1.m_Talk_TWN = "希望您能長話短說，我還有很多文件沒處理。"
L19_1.m_Talk_THA = "ถ้างั้นรบกวนอย่านานได้มั้ยคะ? ฉันยังมีงานเอกสารต้องทำอีกเยอะน่ะค่ะ"
L19_1.m_Talk_VTN = "Chúng ta có thể lướt nhanh đoạn này không? Tôi còn nhiều giấy tờ phải xử lý lắm."
L19_1.m_Talk_SCN = "最好长话短说哦，我还有好多文件没处理。"
L19_1.m_Talk_DEU = "Können wir uns beeilen? Ich habe eine Menge Papierkram zu erledigen."
L19_1.m_Talk_FRA = "Pouvons-nous faire ça vite ? J'ai beaucoup de paperasse qui m'attend."
