L21_1.m_Talk_FRA = "Qu'est-ce que c'est que ce machin ?"
L22_1 = {}
L22_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE4_END@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 14
