L22_1.m_Pos = "L"
L22_1.m_Talk_KOREA = "음? 설명 듣지 못하셨나요?"
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "あら？ 説明を聞いていませんか？"
L22_1.m_Talk_ENG = "Huh? Didn't you hear?"
L22_1.m_Talk_TWN = "嗯？您沒有聽到之前的說明嗎？"
L22_1.m_Talk_THA = "หืม? เขาก็พูดไปแล้วนี่คะ?"
