L22_1.m_Talk_SCN = "嗯？您没有听到之前的说明吗？"
L22_1.m_Talk_DEU = "Hm? Hast du nichts davon gehört?"
L22_1.m_Talk_FRA = "Hein ? Vous ne savez pas ?"
L23_1 = {}
L23_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE4_END@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 14
L23_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L23_1.m_Pos = "L"
L23_1.m_Talk_KOREA = "저 분은 최첨단 과학기술로 만들어진 대인기피용 원격조작 머시노이드 인터페이스......"
L23_1.m_fTalkTime = 0.015
L23_1.m_Talk_JPN = "あの方は、最先端の科学技術で作られた対人忌避用の半自律遠隔操作マシンノイド・インターフェース……"
L23_1.m_Talk_ENG = "He's a remote controlled machinoid interface that was developed with state-of-the-art scientific technology..."
L23_1.m_Talk_TWN = "這位是尖端科學和技術結合的超人氣半自動遠端操控機械介面……"
L23_1.m_Talk_THA = "เขาก็คืออินเทอร์เฟสจักรกลชนิดควบคุมจากระยะไกล ซึ่งพัฒนาขึ้นด้วยความรู้ทางวิทยาศาสตร์อันล้ำสมัย..."
L23_1.m_Talk_VTN = "Anh ta là người máy có giao diện nhân hóa được điều khiển từ xa được phát triển bằng công nghệ khoa học hiện đại nhất..."
L23_1.m_Talk_SCN = "这位是由尖端科技制造的躲避用反自律远程操作莫西诺伊德接口……"
L23_1.m_Talk_DEU = "Er ist eine ferngesteuerte maschinoide Schnittstelle, die mit modernster wissenschaftlicher Technologie entwickelt wurde."
L23_1.m_Talk_FRA = "C'est une interface machinoïde à contrôle distant basée sur une technologie scientifique de pointe..."
