L25_1 = {}
L25_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE4_END@25#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 14
L25_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L25_1.m_bWaitClick = true
