L25_1.m_Pos = "R"
L25_1.m_Crash = 50
L25_1.m_Talk_KOREA = "아니! 누가 그딴 설명을 듣고 싶다고 했어?!"
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "違う！誰がそんな説明を聞きたいって言った！？"
L25_1.m_Talk_ENG = "No! I don't care what it says on the brochure!"
L25_1.m_Talk_TWN = "不是，誰要聽這種說明啊？！"
L25_1.m_Talk_THA = "ไม่ใช่! ฉันไม่สนไอ้ที่เขียนไว้ในโบรชัวร์หรอกน่า!"
L25_1.m_Talk_VTN = "Không! Ta chả quan tâm đến mấy lời trên tờ quảng cáo đâu!"
L25_1.m_Talk_SCN = "不是，谁要听这种说明啊？！"
L25_1.m_Talk_DEU = "Nein, das meine ich nicht! Es ist mir egal, was in der Broschüre steht!"
L25_1.m_Talk_FRA = "Non ! Je me fiche de savoir ce qui est écrit sur le manuel !"
L26_1 = {}
L26_1.m_CutScenKey_Talk = "EP1_ACT1_STAGE4_END@26#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 14
L26_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L26_1.m_Pos = "R"
L26_1.m_Crash = 50
L26_1.m_Talk_KOREA = "대체 저게 뭔데 우리더러 이 고생을 하면서 구출해 오라고 했냐고?!"
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "あれに、私たちが命がけで救出するほどの価値があるのか聞いてるんだ！"
L26_1.m_Talk_ENG = "Why was that thing so important that you had to put us through all that?!"
L26_1.m_Talk_TWN = "那到底是什麼東西啊？要我們費這麼大勁把它救出來？！"
L26_1.m_Talk_THA = "ทำไมเจ้าหุ่นนี่ถึงสำคัญขนาดที่ให้พวกเราไปเสี่ยงตายแบบนั้น?!"
L26_1.m_Talk_VTN = "Tại sao thứ đó lại quan trọng đến nỗi cô phải buộc bọn ta lao thẳng vào hiểm nguy như thế chứ?!"
L26_1.m_Talk_SCN = "那到底是什么啊？让我们费这么大劲去救出来？！"
L26_1.m_Talk_DEU = "Warum war das Ding so wichtig, dass du uns das alles zumuten musstest?"
L26_1.m_Talk_FRA = "Cette chose était-elle importante au point de nous envoyer là-bas ?!"
L27_1 = {}
