L42_1 = "아니, 신임 사장이라니 그게 무슨 소리야? 사장은 너잖아?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "新しい社長ってどういうことだ？ 社長はお前だろ？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "He was appointed president? What are you talking about? But you're the president!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "不是，新任老闆？什麼意思？老闆不是妳嗎？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ไอ้หุ่นเนี่ยนะจะมาเป็นประธาน? พูดอะไรของเธอน่ะ? เธอเป็นประธานไม่ใช่เหรอ!"
L41_1.m_Talk_THA = L42_1
L42_1 = "Anh ta được chỉ định làm chủ tịch á? Cô đang nói cái gì thế hả? Nhưng cô là chủ tịch cơ mà!"
L41_1.m_Talk_VTN = L42_1
L42_1 = "不是，新任老板？什么意思？老板不是你吗？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Er wurde zum Vorsitzenden ernannt? Was redest du da? Du bist doch die Vorsitzende!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Il a été nommé président ? Qu'est-ce que vous racontez ? C'est vous la présidente !"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
