L43_1 = "L_M_I"
L42_1.m_Pos = L43_1
L43_1 = "참고로 전 오늘부터 부사장입니다."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "私は、今日から副社長です。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I'm actually the Vice President starting today."
L42_1.m_Talk_ENG = L43_1
L43_1 = "對，所以我從今天開始就是副總了。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ตั้งแต่วันนี้เป็นต้นไป ฉันก็จะถูกลดตำแหน่งไปเป็นรองประธานแล้วค่ะ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Thực ra kể từ hôm nay tôi sẽ là Phó Chủ Tịch."
L42_1.m_Talk_VTN = L43_1
L43_1 = "对，所以从今天开始我就是副总了。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Na ja, ab heute bin ich Vizevorsitzende."
L42_1.m_Talk_DEU = L43_1
L43_1 = "En fait, je suis la vice-présidente désormais."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
