L43_1.m_Pos = "L"
L44_1 = "다만 신임 사장님께서 업무에 익숙하지 않으신 터라......."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "ただ、新任の社長がまだ業務に慣れていないので……"
L43_1.m_Talk_JPN = L44_1
L44_1 = "But because our new president isn't used to the work yet..."
L43_1.m_Talk_ENG = L44_1
L44_1 = "只是新任老闆還不太熟悉公司業務……"
L43_1.m_Talk_TWN = L44_1
L44_1 = "แต่เนื่องจากประธานคนใหม่ของเรายังไม่ชินกับงาน..."
L43_1.m_Talk_THA = L44_1
L44_1 = "Nhưng bởi vì chủ tịch mới của chúng ta chưa quen với công việc..."
L43_1.m_Talk_VTN = L44_1
L44_1 = "只是新任老板暂时还不熟悉公司业务，"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Aber da unser neuer Vorsitzender die Arbeit noch nicht gewöhnt ist …"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Mais comme notre nouveau président n'est pas encore habitué à ses fonctions..."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
