L45_1 = "당분간 실무는 이전처럼 제가 대행할 예정입니다."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "当分の間は、私が代行する予定です。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I'll be running the company as usual during the transition."
L44_1.m_Talk_ENG = L45_1
L45_1 = "所以短期內會由我代為處理。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ฉันก็จะรับหน้าที่บริหารบริษัทต่อไปตามปกติในช่วงเปลี่ยนผ่านนี้"
L44_1.m_Talk_THA = L45_1
L45_1 = "Tôi vẫn sẽ điều hành công ty như thường lệ trong quá trình chuyển đổi."
L44_1.m_Talk_VTN = L45_1
L45_1 = "所以短期内将会由我代为处理公司业务。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "… werde ich das Unternehmen während der Übergangsphase wie gewohnt weiterführen."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Je continuerai à diriger l'entreprise pendant la transition."
L44_1.m_Talk_FRA = L45_1
