L4_1 = "신임 사장님께서는 오늘 부로 코핀 컴퍼니의 모든 주식을 인수하셔서 최대 주주가 되셨습니다."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "新しい社長は本日付でコフィンカンパニーの株式をすべて買い取り、筆頭株主になられたのです。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Our new president acquired all of Coffin Company's stock today and became the majority shareholder."
L3_1.m_Talk_ENG = L4_1
L4_1 = "新任老闆收購了科芬公司的所有股份，所以從今天開始，它就是公司最大的股東。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ประธานคนใหม่ของเราเข้าซื้อหุ้นทั้งหมดของบริษัทคอฟฟินในวันนี้ ทำให้เขาเป็นผู้ถือหุ้นใหญ่"
L3_1.m_Talk_THA = L4_1
L4_1 = "Hôm nay chủ tịch mới của chúng ta đã mua tất cả cổ phiếu của Công Ty Coffin và trở thành cổ đông chính."
L3_1.m_Talk_VTN = L4_1
L4_1 = "新任老板收购了科芬公司的全部股份，从今天开始是公司最大的股东。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Unser neuer Vorsitzender hat heute alle Aktien der Coffin Company erworben und ist zum Mehrheitsaktionär geworden."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Notre nouveau président a acquis toutes les actions de la Compagnie Coffin aujourd'hui et est devenu l'actionnaire majoritaire."
L3_1.m_Talk_FRA = L4_1
