L14_1 = "不，等一下……我現在有點跟不上對話了。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "เดี๋ยวสิ... ฉันว่าฉันตามไม่ทันแล้วล่ะ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Chờ một chút đã... Ta không chắc là mình theo kịp."
L13_1.m_Talk_VTN = L14_1
L14_1 = "不是，等一下……我现在有点儿跟不上你的节奏了，"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Jetzt noch mal in Ruhe. Ich bin mir nicht sicher, ob ich folgen kann."
L13_1.m_Talk_DEU = L14_1
