L14_1.m_Pos = "C"
L15_1 = "사장이나 최대 주주니...... 그건 일단 제쳐 두고."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "社長やら筆頭株主やらは置いておいて、"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Stocks? Majority shareholder? Okay, let's put that aside for now."
L14_1.m_Talk_ENG = L15_1
L15_1 = "什麼老闆，什麼最大股東……先不管這些。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "หุ้น? ผู้ถือหุ้นใหญ่? เอาล่ะ เรื่องนั้นเอาไว้ก่อน"
L14_1.m_Talk_THA = L15_1
L15_1 = "Cổ phiếu ư? Cổ đông chính ư? Được rồi, giờ hãy để mấy thứ đó sang một bên đã."
L14_1.m_Talk_VTN = L15_1
L15_1 = "什么老板，什么最大股东……先不管这些。"
L14_1.m_Talk_SCN = L15_1
