L16_1 = "회사가 망했다는 건 또 무슨 소리야?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "会社がつぶれたとは何ごとだ？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Has the company really gone bankrupt?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "公司倒閉了？這又是什麼意思？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "บริษัทของเราล้มละลายจริงๆ เหรอ?"
L15_1.m_Talk_THA = L16_1
L16_1 = "Công ty này thực sự phá sản rồi sao?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "公司倒闭了？这又是什么意思？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Aber ist das Unternehmen wirklich bankrott gegangen?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "L'entreprise a réellement fait faillite ?"
L15_1.m_Talk_FRA = L16_1
