L17_1 = "우리 회사가 작긴 해도 갑자기 망하거나 할 정도는 아니었잖아?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "規模は小さくても、急につぶれるほどでははなかったはずだ。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "The company might be small, but it was never doing that bad!"
L16_1.m_Talk_ENG = L17_1
L17_1 = "就算我們公司不大，也不至於突然倒閉吧？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ถึงบริษัทนี้จะไม่ได้ใหญ่โต แต่ธุรกิจของเราก็ไม่เคยย่ำแย่ขนาดนี้นี่นา!"
L16_1.m_Talk_THA = L17_1
L17_1 = "Công ty này có thể nhỏ, nhưng chưa bao giờ tệ như thế cả!"
L16_1.m_Talk_VTN = L17_1
L17_1 = "就算我们公司不大，也不至于说倒闭就倒闭吧？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Das Unternehmen mag klein sein, aber so schlecht lief es doch nie!"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Elle est peut-être petite, mais elle ne s'est jamais si mal portée !"
L16_1.m_Talk_FRA = L17_1
