L18_1 = "관리국에서 넘버링 라이선스까지 받은 알짜기업이었다고!!"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "管理局からナンバリングライセンスをもらえるほどの優良企業だったのに！！"
L17_1.m_Talk_JPN = L18_1
L18_1 = "We're one of the few companies actually licensed by the Administration!"
L17_1.m_Talk_ENG = L18_1
L18_1 = "我們不是有管理局編號證書的精銳企業嗎！！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "เราเป็นหนึ่งในไม่กี่บริษัทที่ได้ใบอนุญาตจากองค์การบริหารโลกเลยนะ!"
L17_1.m_Talk_THA = L18_1
L18_1 = "Chúng ta là một trong số ít các công ty tư nhân thực sự được Cục Quản Lý cấp phép!"
L17_1.m_Talk_VTN = L18_1
L18_1 = "我们不是拿到管理局编号证书的精锐企业吗！！"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Wir sind eins der wenigen Unternehmen, die von der Administration lizenziert sind!"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Nous sommes l'une des rares entreprises réellement agréées par l'Administration !"
L17_1.m_Talk_FRA = L18_1
