L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "R"
L22_1 = "뭐, 그랬던 적도 있었죠."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "そんな時期もありましたね。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Those were the good old days."
L21_1.m_Talk_ENG = L22_1
L22_1 = "嗯，曾經有過這樣的殊榮呢。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "แต่นั่นเป็นเรื่องในอดีตไปแล้ว"
L21_1.m_Talk_THA = L22_1
L22_1 = "Đó là những ngày tốt đẹp xa xưa."
L21_1.m_Talk_VTN = L22_1
L22_1 = "嗯，曾经有过这样的荣誉呢。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Das waren die guten alten Zeiten."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Le bon vieux temps."
L21_1.m_Talk_FRA = L22_1
