L23_1 = "EP1_ACT1_STAGE4_END@72#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 14
L22_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L22_1.m_Pos = "L"
L23_1 = "지금은 초과근무, 임금체불, 평판최악의 트리플 크라운을 달성한 훌륭한 블랙기업입니다."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "今では超過勤務、賃金未払い、評判最悪の三冠を達成した優良ブラック企業です。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "But now we're just infamous for endless overtime, overdue wages, and a disastrous reputation."
L22_1.m_Talk_ENG = L23_1
L23_1 = "不過現在是加班時間過長、拖欠薪資、名聲最糟糕的第一黑心企業。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ตอนนี้ เราเป็นที่โด่งดังในเรื่องโอทีไม่มีวันจบ ค้างเงินเดือนพนักงาน แล้วก็เรื่องเสื่อมเสียมากมาย"
L22_1.m_Talk_THA = L23_1
L23_1 = "Nhưng bây giờ chúng ta chỉ nổi tiếng với thời gian làm thêm vô tận, trả lương trễ và danh tiếng thảm hại thôi."
L22_1.m_Talk_VTN = L23_1
L23_1 = "不过现在是在加班时间长、拖欠薪水、名声最糟糕等，第一优秀黑心企业。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Aber jetzt sind wir ein Unternehmen mit endlosen Überstunden, überfälligen Löhnen und einem katastrophalen Ruf."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Désormais, nous sommes célèbres pour nos heures supplémentaires à rallonge, nos retards de paiements et notre désastreuse réputation."
L22_1.m_Talk_FRA = L23_1
