L28_1 = "나도 두통이 오는군."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "私も頭痛が……"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Yeah, and I'm getting a headache."
L27_1.m_Talk_ENG = L28_1
L28_1 = "我也開始頭痛了。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "นั่นสิ ฉันเองก็เริ่มปวดหัวขึ้นมาแล้ว"
L27_1.m_Talk_THA = L28_1
L28_1 = "Ừ, còn ta thì chuẩn bị đau đầu rồi."
