L29_1 = "EP1_ACT1_STAGE4_END@78#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 78
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 14
L28_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L28_1.m_Pos = "L"
L29_1 = "그러고 보니 현장에서도 좀 이상했어."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "そういや現場でもおかしいなとは思った。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Come to think of it, I thought something smelled fishy out there."
L28_1.m_Talk_ENG = L29_1
L29_1 = "這麼說來，之前在作戰現場就覺得有點奇怪了。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "จะว่าไป ฉันก็รู้สึกไม่ชอบมาพากลตั้งแต่แรกแล้ว"
L28_1.m_Talk_THA = L29_1
L29_1 = "Nghĩ kỹ thì ta thấy có mùi gì đó ám muội ở đây."
L28_1.m_Talk_VTN = L29_1
L29_1 = "这么一说，之前在作战现场就有点儿奇怪了。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Wenn ich so darüber nachdenke … Ich dachte mir gleich, dass hier etwas faul ist."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Je me disais bien qu'il se passait quelque chose de louche ici."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "EP1_ACT1_STAGE4_END@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 14
L29_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L29_1.m_Pos = "L"
L30_1 = "하나 씨가 갑자기 작전부에 나타나질 않나, 가용 부대가 하나도 없다고 하질 않나......."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "スズカが急に作戦部に現れたり、他に稼働部隊がないと言われたりな……"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Hana suddenly showing up at the Operation Department... And how we're the only available squad..."
L29_1.m_Talk_ENG = L30_1
L30_1 = "為什麼金荷娜突然出現在作戰部，公司裡還連一個能出動的小隊都沒有……"
L29_1.m_Talk_TWN = L30_1
L30_1 = "จู่ๆ ฮานาก็อยู่แผนกปฏิบัติการ... แถมพวกเรายังเป็นหน่วยเดียวในบริษัทที่ออกปฏิบัติการได้..."
L29_1.m_Talk_THA = L30_1
L30_1 = "Hana đột nhiên xuất hiện tại Bộ Phận Điều Hành... Rồi chúng ta lại trở thành tiểu đội duy nhất có thể huy động..."
L29_1.m_Talk_VTN = L30_1
L30_1 = "为什么千夜突然出现在作战部，而且公司里只有一支能出动的小队……"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Hana tauchte plötzlich in der Einsatzabteilung auf … Und wir waren die einzige verfügbare Einheit …"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Hana qui débarque subitement au département des opérations... Et le fait que nous soyons la seule escouade disponible..."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "EP1_ACT1_STAGE4_END@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 14
L30_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L30_1.m_Pos = "L"
L31_1 = "게다가 이 고물 배 말고 다른 함선들은 다 어디로 간 거야?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "それに、このボロ船以外の艦船は全部どこにいったんだ？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "And where did all the ships go? Don't tell me this piece of junk is all that's left."
L30_1.m_Talk_ENG = L31_1
L31_1 = "而且為什麼我只看見這艘破船？公司的其它艦船去哪裡了？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "แล้วยานรบของเราไปไหนหมดล่ะ? อย่าบอกนะว่าตอนนี้เหลือแค่เศษเหล็กนี่"
L30_1.m_Talk_THA = L31_1
L31_1 = "Rồi còn mấy cái tàu đi đâu hết rồi? Đừng nói với ta là chúng ta chỉ còn lại mấy mảnh rác này thôi đấy."
L30_1.m_Talk_VTN = L31_1
L31_1 = "还有，怎么只看见这只旧船？公司里的其它舰船去哪里了？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Und wo sind all die Schiffe hin? Sagt bloß, dass nur noch dieser Schrotthaufen übrig ist …"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Où sont passés tous les vaisseaux ? Ne me dites pas que ce tas de ferraille est tout ce qui nous reste."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
