L32_1.m_Face = "UNIT_IDLE"
L32_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "작전부는 월급이 밀려서 해체했습니다."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "作戦部は賃金未払いの影響で解散しました。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "We had to disband the Operation Department because we couldn't pay the staff."
L32_1.m_Talk_ENG = L33_1
L33_1 = "作戰部因為一直拖欠薪水，所以解散了。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เราต้องยุบแผนกปฏิบัติการไปเพราะว่าไม่มีเงินจ่ายค่าจ้างพนักงานค่ะ"
L32_1.m_Talk_THA = L33_1
L33_1 = "Chúng ta phải giải tán Bộ Phận Điều Hành bởi vì không thể trả lương cho nhân viên."
L32_1.m_Talk_VTN = L33_1
L33_1 = "作战部因为一直拖欠着工资，所以解散了，"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Wir mussten die Einsatzabteilung auflösen, weil wir das Personal nicht bezahlen konnten."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Nous avons dû dissoudre le département des opérations, car nous ne pouvions plus payer le personnel."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "EP1_ACT1_STAGE4_END@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 14
L33_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L33_1.m_Pos = "C"
L34_1 = "지금은 관리부에서 임시로 업무 대행 중이죠."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "今はとりあえず管理部で業務を代行しています。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "So the Managerial Department is filling in for Operation Department work now."
L33_1.m_Talk_ENG = L34_1
L34_1 = "現在由管理部暫時代理作戰部的工作。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ตอนนี้แผนกบริหารก็เลยต้องทำงานแทนแผนกปฏิบัติการไปก่อน"
L33_1.m_Talk_THA = L34_1
L34_1 = "Vậy nên lúc này Bộ Phận Quản Lý phải đảm nhiệm công việc của Bộ Phận Điều Hành."
L33_1.m_Talk_VTN = L34_1
L34_1 = "现在由管理部暂时代理作战部工作。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Daher übernimmt jetzt die Führungsabteilung die Aufgaben der Einsatzabteilung."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Du coup, ce sont les gens de la Direction qui remplissent le rôle du département des opérations pour le moment."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP1_ACT1_STAGE4_END@84#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 14
L34_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L34_1.m_Pos = "C"
L35_1 = "베테랑 대원들은 벌써 작년에 따로 나가서 회사를 차렸습니다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ベテランの隊員たちは、去年別会社をつくって出ていきました。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "The more seasoned employees already left last year and started their own companies."
L34_1.m_Talk_ENG = L35_1
L35_1 = "之前的隊員都在去年一個個離開，並在外面成立了公司。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "พนักงานเก่งๆ ของเราก็เพิ่งลาออกไปเมื่อปีที่แล้ว เพื่อออกไปเปิดบริษัทของตัวเอง"
L34_1.m_Talk_THA = L35_1
L35_1 = "Các nhân viên dày dạn hơn đã rời đi từ năm ngoái và thành lập công ty riêng của mình rồi."
L34_1.m_Talk_VTN = L35_1
L35_1 = "之前的队员们去年都已经一个个离开，在外面成立了公司，"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Erfahrene Mitarbeiter haben das Unternehmen bereits im letzten Jahr verlassen und eigene Unternehmen gegründet."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Les employés les plus qualifiés sont déjà partis l'année dernière et ont créé leurs propres entreprises."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP1_ACT1_STAGE4_END@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 14
L35_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L35_1.m_Pos = "C"
L36_1 = "이전 작전부 직원들이 대거 그쪽으로 이직했다고 하더군요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "以前の作戦部スタッフたちが大勢そちらに転職したそうです。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I heard that most of our Operation Department folks are working over there now."
L35_1.m_Talk_ENG = L36_1
L36_1 = "聽說作戰部的員工大多都跳槽到他們開的公司去了。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ฉันได้ยินมาว่าคนจากแผนกปฏิบัติการส่วนใหญ่ก็ไปทำงานที่นั่นกันหมดแล้ว"
L35_1.m_Talk_THA = L36_1
L36_1 = "Tôi nghe nói các lão làng trong Bộ Phận Điều Hành giờ đang làm việc ở đằng kia."
L35_1.m_Talk_VTN = L36_1
L36_1 = "听说作战部的职员们大多跳槽到他们开的公司去了。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Soweit ich weiß, arbeiten die meisten Mitarbeiter unserer Einsatzabteilung mittlerweile anderswo."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Il paraît que la plupart des employés de notre département des opérations travaillent pour eux, désormais."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP1_ACT1_STAGE4_END@86#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 86
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 14
L36_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L36_1.m_Pos = "C"
L37_1 = "그리고 다른 함선들은 전부 고철로 팔았습니다."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "あと、他の艦船はすべて、くず鉄として売り払いました。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "As for the rest of our ships, we sold them for scrap."
L36_1.m_Talk_ENG = L37_1
L37_1 = "然後艦船也都當作廢鐵賣掉了。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ส่วนยานที่เหลือเราก็ขายเป็นเศษเหล็กไปหมดแล้วล่ะค่ะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Đối với số tàu còn lại, chúng tôi đã bán phế liệu rồi."
L36_1.m_Talk_VTN = L37_1
L37_1 = "然后舰船也都当做废铁卖掉了。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Den Rest unserer Schiffe haben wir als Schrott verkauft."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Quant à nos autres vaisseaux, nous les avons vendus en pièces détachées."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP1_ACT1_STAGE4_END@87#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 87
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 14
L37_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L37_1.m_Pos = "C"
L38_1 = "지금쯤 보온병 같은 걸로 재활용 되지 않았을까 싶네요."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "今頃、魔法瓶などにリサイクルされているかもしれませんね。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "They've probably been recycled into license plates or something by now."
L37_1.m_Talk_ENG = L38_1
L38_1 = "我想那些船大概已經被回收掉，做成保溫杯之類的東西。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ตอนนี้น่าจะโดนรีไซเคิลเป็นป้ายทะเบียนหรืออะไรสักอย่างไปแล้ว"
L37_1.m_Talk_THA = L38_1
L38_1 = "Bây giờ có lẽ chúng đã được tái chế thành biển số xe hoặc thứ gì đó luôn rồi."
L37_1.m_Talk_VTN = L38_1
L38_1 = "我想那些船大概已经被回收掉，做成保温杯之类的东西了吧。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Wahrscheinlich sind sie inzwischen zu Nummernschildern oder Ähnlichem recycelt worden."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Ils ont dû être recyclés en plaques d'immatriculation ou je ne sais quoi à l'heure qu'il est."
L37_1.m_Talk_FRA = L38_1
