L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 90
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 14
L40_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
