L41_1 = "UNIT_SERIOUS"
L40_1.m_Face = L41_1
L40_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L40_1.m_Pos = "C"
L41_1 = "그리고 넌 사장이라는 게 회사가 그 꼴이 나도록 가만있었어?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "お前は社長のくせに会社がこのザマになるまで何してたんだ？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "You're the president! What were you doing while the company was sinking?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "妳不是老闆嗎？妳就眼睜睜地看著公司變成這個樣子？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เธอเป็นประธานไม่ใช่เหรอ! มัวทำอะไรอยู่ตอนที่บริษัทกำลังย่ำแย่?"
L40_1.m_Talk_THA = L41_1
L41_1 = "Cô là chủ tịch cơ mà! Cô đã làm gì trong lúc công ty sa vào cảnh lụn bại như vậy hả?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "你不是老板吗？你就眼睁睁地看着公司变成这幅样子？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Du bist die Vorsitzende! Was hast du getan, während das Unternehmen den Bach runterging?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Vous êtes la présidente ! Qu'est-ce que vous fabriquiez pendant que l'entreprise était en train de couler ?"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP1_ACT1_STAGE4_END@91#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 91
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 14
L41_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L41_1.m_Pos = "C"
L41_1.m_Crash = 50
L42_1 = "나 없는 동안 대체 뭔 짓을 한 거야?!"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "私がいない間、いったい何があったんだ！？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "What did you do while I was gone?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "我不在的時候妳到底幹了些什麼啊？！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "เธอทำอะไรอยู่ตอนที่ฉันไม่อยู่?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Cô đã làm gì trong lúc ta vắng mặt vậy hả?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "我不在的时候你到底干了些什么啊？！"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Was hast du getan, während ich weg war?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Qu'est-ce que vous avez fait en mon absence ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
