L48_1 = "UNIT_HATE"
L47_1.m_Face = L48_1
L47_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L47_1.m_Pos = "C"
L48_1 = "......뭐? 왜? 뭐?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "……なんだ？なんだよ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "...What? Why? What?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "……啊？幹嘛啊？怎樣？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "...อะไร? ทำไมเหรอ? มีอะไร?"
L47_1.m_Talk_THA = L48_1
L48_1 = "...Hả? Sao? Cái gì?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "……啊？干吗啊？说！"
L47_1.m_Talk_SCN = L48_1
L48_1 = "… Wie? Warum? Was?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Quoi...? Pourquoi ? Quoi ?"
L47_1.m_Talk_FRA = L48_1
