L51_1 = "EP1_ACT1_STAGE4_END@100#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 100
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 14
L50_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
