L51_1 = "UNIT_LAUGH"
L50_1.m_Face = L51_1
L50_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L50_1.m_Pos = "L"
L51_1 = "이 모든 사달의 주역께서 그런 이야기를 하시면 곤란하죠."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "すべての元凶にそんなことを言われたら困りますね。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "It's a bit awkward to hear you say that, when you're the reason for all this."
L50_1.m_Talk_ENG = L51_1
L51_1 = "聽到造成一切問題的罪魁禍首說出這種話，我也很困擾啊。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "มันก็รู้สึกแปลกๆ น่ะค่ะ ที่ได้ยินคุณพูดแบบนั้น ทั้งๆ ที่คุณนั่นแหละคือต้นเหตุของเรื่องทั้งหมด"
L50_1.m_Talk_THA = L51_1
L51_1 = "Nghe người nói thế làm tôi thấy hơi ngượng ngạo đấy, vì người chính là nguyên nhân của tất cả những việc này mà."
L50_1.m_Talk_VTN = L51_1
L51_1 = "听到一切问题的罪魁祸首说出这种话，我也很困扰啊。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Es ist mir unangenehm, das von dir zu hören … da du der Grund für das alles bist."
L50_1.m_Talk_DEU = L51_1
L51_1 = "C'est un peu gênant de vous entendre dire ça alors que vous en êtes la cause principale."
L50_1.m_Talk_FRA = L51_1
