L2_1 = "EP1_ACT1_STAGE4_END@101#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 101
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 14
L1_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "R"
L2_1 = "그렇습니다. 다른 말로 적반하장, 객반위주, 아가사창이라고도 하죠."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "ですね。言い換えると、「居直り」「盗っ人猛々しい」「逆切れ」とも言いますね。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "She's right. This is a classic example of \"the pot calling the kettle black.\""
L1_1.m_Talk_ENG = L2_1
L2_1 = "沒錯，俗話說就是“作賊喊捉賊”、“反客為主”、“惡人先告狀”吧。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "เธอพูดถูกแล้วล่ะครับ นี่ล่ะ ตัวอย่างชั้นดีของสำนวน \"หม้อเองก็ก้นดำ ยังมีหน้าไปหาว่ากาน้ำก้นดำอีก\""
L1_1.m_Talk_THA = L2_1
L2_1 = "Cô ấy nói đúng đó. Đây là một ví dụ điển hình cho câu nói \"chó chê mèo lắm lông\" đấy."
L1_1.m_Talk_VTN = L2_1
L2_1 = "没错，俗话说就是“贼喊捉贼”、“反客为主”、“倒打一耙”吧。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Sie hat recht. Wie heißt es doch? „Wer im Glashaus sitzt, soll nicht mit Steinen werfen.“"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Elle a raison. C'est un cas typique de « l'hôpital qui se fout de la charité. »"
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "EP1_ACT1_STAGE4_END@102#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 102
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 14
L2_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L2_1.m_Pos = "L"
L3_1 = "시윤 군. 자네에게는 유유상종, 초록동색, 청출어람이라는 말을 해 주고 싶군."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "アキヤマ君。そんなあなたには、「類は友を呼ぶ」「牛は牛連れ、馬は馬連れ」「藍より青し」と言いたいわね。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Shiyoon. And you're the perfect example of \"the apple doesn't fall far from the tree. \""
L2_1.m_Talk_ENG = L3_1
L3_1 = "時雲君，我比較想對你說“物以類聚”、“青出於藍勝於藍”呢。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ชิยุน ส่วนเธอน่ะ ก็เป็นตัวอย่างชั้นดีของสำนวน \"ลูกไม้หล่นไม่ไกลต้น\""
L2_1.m_Talk_THA = L3_1
L3_1 = "Shiyoon. Còn cậu là minh chứng hoàn hảo cho câu \"con nhà tông không giống lông cũng giống cánh.\""
L2_1.m_Talk_VTN = L3_1
L3_1 = "时云君，我比较想对你说“物以类聚”、“青出于蓝胜于蓝”呢。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Shiyoon, bei dir fällt mir eher ein: „Der Apfel fällt nicht weit vom Stamm.“"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Et toi, Charles, tu es un parfait exemple de « la pomme qui ne tombe jamais loin de l'arbre. »"
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "EP1_ACT1_STAGE4_END@103#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 103
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 14
L3_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L3_1.m_Pos = "L"
L4_1 = "그리고 당장 입 다물지 않으면 밀린 자네 월급이 회계 절차상의 문제로 영원히 지급되지 않을 수도 있네."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "あと、今すぐに口をつぐまなければ、未払い分の給料は会計上の問題で永久に支払われないかも知れないわよ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "And if you don't shut your trap this instant, I'll make sure you never see your next paycheck."
L3_1.m_Talk_ENG = L4_1
L4_1 = "然後你再不閉嘴的話，你還沒結清的薪水就永遠別想拿到了。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "แล้วถ้าเธอยังไม่หยุดพูดอีก รับรองว่าเธอจะไม่มีวันได้เห็นเช็คเงินเดือนอีกเลยตลอดชีวิต"
L3_1.m_Talk_THA = L4_1
L4_1 = "Và nếu cậu không ngậm mồm lại ngay lập tức, tôi sẽ đảm bảo cậu sẽ không bao giờ nhìn thấy tiền lương tháng tới của mình đâu."
L3_1.m_Talk_VTN = L4_1
L4_1 = "再不闭嘴的话，你没结清的工资可能永远也拿不到了喔。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Und wenn du nicht sofort deine Klappe hältst, sorge ich dafür, dass du deinen nächsten Gehaltsscheck nie zu Gesicht bekommen wirst."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Et si tu ne te tais pas sur le champ, je m'assurerai que tu ne voies plus jamais la couleur d'un bulletin de salaire."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "EP1_ACT1_STAGE4_END@104#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 14
L4_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "R"
L5_1 = "......부사장님. 저는 입이 없습니다."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "……副社長、僕には口なんてありません。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Madame Vice President... Consider this trap shut."
L4_1.m_Talk_ENG = L5_1
L5_1 = "……報告副總，我的嘴巴已經被縫上了。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ได้ครับรองประธาน... ผมจะรูดซิปปากให้สนิทเลยครับ"
L4_1.m_Talk_THA = L5_1
L5_1 = "Quý Cô Phó Chủ Tịch... Hãy xem như tôi chưa nói gì nhé."
L4_1.m_Talk_VTN = L5_1
L5_1 = "……报告副总，我的嘴巴已经被缝上了。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Frau Vizevorsitzende, betrachten Sie diese Klappe als geschlossen."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Madame la vice-présidente... je serai muet comme une tombe."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
