L8_1 = "UNIT_LAUGH"
L7_1.m_Face = L8_1
L7_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L7_1.m_Pos = "C"
L8_1 = "자네의 사회생활 방식은 볼 때마다 감탄스럽군."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "君の処世術にはいつも感心させられるわね。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "I do love your work ethic."
L7_1.m_Talk_ENG = L8_1
L8_1 = "你的職場生存方式每次都令我歎為觀止呢。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ฉันชอบจรรยาบรรณการทำงานของเธอจริงๆ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Tôi thích tác phong làm việc của cậu đấy."
L7_1.m_Talk_VTN = L8_1
L8_1 = "你的职场生存方式，每次都令我叹为观止呢。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ich liebe deine Arbeitsmoral."
L7_1.m_Talk_DEU = L8_1
L8_1 = "J'aime ta déontologie professionnelle."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "EP1_ACT1_STAGE4_END@108#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 108
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 14
L8_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L8_1.m_Pos = "C"
L9_1 = "부디 그 자세가 앞으로도 변치 않길 바라네."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "どうかその姿勢が、これからも変わらないことを願うわ。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I hope it'll never change."
L8_1.m_Talk_ENG = L9_1
L9_1 = "希望你以後也能保持這種態度。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ขอให้ทำดีแบบนี้ต่อไปเรื่อยๆ นะ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Hy vọng cậu sẽ không bao giờ thay đổi."
L8_1.m_Talk_VTN = L9_1
L9_1 = "希望你以后也能保持这种态度。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ich hoffe, sie wird sich nie ändern."
L8_1.m_Talk_DEU = L9_1
L9_1 = "J'espère qu'elle ne changera jamais."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "EP1_ACT1_STAGE4_END@109#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 109
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 14
L9_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L9_1.m_Pos = "C"
L10_1 = "어쨌든 저간의 사정을 잘 모르시는 것 같으니 설명을 해 드리죠."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "とにかく、これまでの事情をあまり知らないようですので、説明しましょう。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Anyway, let me explain what's been going on since you clearly don't have a clue."
L9_1.m_Talk_ENG = L10_1
L10_1 = "師父，您好像還不是很了解公司近來的狀況，就讓我來為您說明一下吧。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "เอาเถอะ ฉันจะอธิบายเองค่ะว่าเกิดอะไรขึ้น เพราะเห็นได้ชัดว่าคุณไม่เข้าใจอะไรเลย"
L9_1.m_Talk_THA = L10_1
L10_1 = "Dù gì thì cũng để tôi giải thích những chuyện đã xảy ra vì rõ ràng là người không biết gì cả."
L9_1.m_Talk_VTN = L10_1
L10_1 = "老师，您好像还不是很了解公司的近况，就让我为您说明一下吧。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Wie auch immer, lass mich erklären, was hier vor sich geht, da du offensichtlich keine Ahnung hast."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Enfin bref, laissez-moi vous expliquer ce qui s'est passé puisqu'à l'évidence vous n'en avez pas la moindre idée."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "EP1_ACT1_STAGE4_END@110#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 110
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 14
L10_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L10_1.m_Pos = "C"
L11_1 = "아시다시피 저희 회사의 카운터 소대는 스승님의 펜릴 소대 하나입니다."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ご存じのように、わが社のカウンター小隊は\n師匠が率いるフェンリル小隊のみです。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "As you know, your Fenrir Squad is the only Counter squad in the entire company."
L10_1.m_Talk_ENG = L11_1
L11_1 = "正如您所知，本公司的制裁者小隊只有師父的芬里爾小隊一支。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "อย่างที่คุณรู้ หน่วยเฟนเรียร์ของอาจารย์เป็นหน่วยเคาน์เตอร์เพียงหน่วยเดียวของบริษัท"
L10_1.m_Talk_THA = L11_1
L11_1 = "Như người đã biết, Tiểu Đội Fenrir của người là Tiểu đội Counter duy nhất trong công ty."
L10_1.m_Talk_VTN = L11_1
L11_1 = "正如您所知，本公司的制裁者小队只有老师的芬里尔小队一支。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Wie du weißt, ist dein Fenrir-Trupp der einzige Countertrupp des gesamten Unternehmens."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Comme vous le savez, Fenrir est la seule escouade de Counters dans toute l'entreprise."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "EP1_ACT1_STAGE4_END@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 14
L11_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L11_1.m_Pos = "C"
L12_1 = "뭐, 당시에는 그게 딱히 문제가 되진 않았죠."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "まあ、当時はそれでもとくに問題にはなりませんでしたね。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "That wasn't a big problem back then..."
L11_1.m_Talk_ENG = L12_1
L12_1 = "不過這也不是什麼大問題。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ในสมัยนั้นมันก็ไม่ใช่ปัญหาใหญ่อะไร..."
L11_1.m_Talk_THA = L12_1
L12_1 = "Lúc đó đây không phải là vấn đề gì lớn..."
L11_1.m_Talk_VTN = L12_1
L12_1 = "不过这也不是什么大问题。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Früher war das kein großes Problem …"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Ça n'était pas vraiment un problème à l'époque..."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "EP1_ACT1_STAGE4_END@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 14
L12_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L12_1.m_Pos = "C"
L13_1 = "하나뿐이지만 펜릴 소대의 전투력은 업계에서도 상위 랭크로 평가되고 있었으니까요."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "たった一つの小隊でも、フェンリル小隊は戦闘力で業界から高い評価をもらってましたから。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Especially since Fenrir was ranked as one of most capable squads in the industry."
L12_1.m_Talk_ENG = L13_1
L13_1 = "雖說只有一支小隊，但芬里爾小隊的戰鬥力在業界中仍是名列前茅。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ยิ่งในตอนนั้น เฟนเรียร์เป็นหนึ่งในหน่วยที่เก่งที่สุดในวงการด้วย"
L12_1.m_Talk_THA = L13_1
L13_1 = "Đặc biệt là kể từ khi Fenrir được xếp hạng là một trong những tiểu đội giỏi nhất trong ngành."
L12_1.m_Talk_VTN = L13_1
L13_1 = "虽说只有一支小队，但芬里尔小队的战斗力在业界中名列前茅。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Zumal Fenrir als einer der fähigsten Trupps der Branche galt."
L12_1.m_Talk_DEU = L13_1
L13_1 = "D'autant moins que Fenrir était l'une des escouades les plus compétentes de l'industrie."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "EP1_ACT1_STAGE4_END@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 14
L13_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L13_1.m_Pos = "C"
L14_1 = "하지만 스승님께서 <color=#ffd34c>멋대로</color> 잠적해 버린 탓에......."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "ですが、師匠が<color=#ffd34c>勝手に</color> 行方をくらましたせいで……"
L13_1.m_Talk_JPN = L14_1
L14_1 = "But ever since you vanished <color=#ffd34c>on a whim</color>..."
L13_1.m_Talk_ENG = L14_1
L14_1 = "不過因為師父 <color=#ffd34c>擅自</color> 消失……"
L13_1.m_Talk_TWN = L14_1
L14_1 = "แต่พอคุณ<color=#ffd34c>จู่ๆ</color> ก็หายตัวไป..."
L13_1.m_Talk_THA = L14_1
L14_1 = "Nhưng vì người đã biến mất <color=#ffd34c>một cách vô trách nhiệm</color>..."
L13_1.m_Talk_VTN = L14_1
L14_1 = "不过因为老师 <color=#ffd34c>擅自</color> 消失，"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Aber dann warst du <color=#ffd34c>mir nichts, dir nichts</color> verschwunden."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Mais depuis que vous vous êtes volatilisée <color=#ffd34c>sur un coup de tête</color>..."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "EP1_ACT1_STAGE4_END@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 14
L14_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L14_1.m_Pos = "C"
L15_1 = "펜릴 소대는 졸지에 지휘관이 사라진 부대가 되었습니다."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "フェンリル小隊はとつぜん指揮官を失ってしまいました。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "The Fenrir Squad was left without a commander."
L14_1.m_Talk_ENG = L15_1
L15_1 = "芬里爾小隊就突然沒了指揮官。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "หน่วยเฟนเรียร์ก็เลยไม่มีผู้บัญชาการ"
L14_1.m_Talk_THA = L15_1
L15_1 = "Tiểu Đội Fenrir chẳng có ai làm Tổng Tư Lệnh nữa."
L14_1.m_Talk_VTN = L15_1
L15_1 = "芬里尔小队突然没有了指挥官。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Der Fenrir-Trupp stand plötzlich ohne Kommandantin da."
L14_1.m_Talk_DEU = L15_1
L15_1 = "L'escouade Fenrir est restée sans commandant à sa tête."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EP1_ACT1_STAGE4_END@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 14
L15_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L15_1.m_Pos = "C"
L16_1 = "안 그래도 스승님의 <color=#ffd34c>저돌적인</color>......."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "もとから師匠の<color=#ffd34c>猪突猛進な</color>……"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Worse yet, given your <color=#ffd34c>reckless</color> style of tactical leadership..."
L15_1.m_Talk_ENG = L16_1
L16_1 = "本來芬里爾小隊就以師父的<color=#ffd34c>魯莽</color>……"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ที่แย่ไปกว่านั้น เนื่องจากอาจารย์มีสไตล์การดำเนินยุทธวิธีรบแบบ<color=#ffd34c>บ้าบิ่น</color>..."
L15_1.m_Talk_THA = L16_1
L16_1 = "Tệ hơn nữa, vì phong cách lãnh đạo chiến thuật <color=#ffd34c>liều lĩnh</color> danh tiếng của người..."
L15_1.m_Talk_VTN = L16_1
L16_1 = "本来芬里尔小队就以老师的<color=#ffd34c>鲁莽</color>，"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Schlimmer noch, infolge deines <color=#ffd34c>draufgängerischen</color> taktischen Führungsstils …"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Encore pire, étant donné votre style tactique <color=#ffd34c>téméraire</color>..."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "EP1_ACT1_STAGE4_END@116#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 14
L16_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L16_1.m_Pos = "C"
L17_1 = "업계 용어로는 <color=#ffd34c>프래깅 제조용</color> 전술지휘로 유명한 펜릴 소대였으니......."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "業界用語だと、<color=#ffd34c>味方殺し</color>の戦術指揮で有名なフェンリル小隊でしたから……"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Which folks in the industry call <color=#ffd34c>\"frag-inducing\"</color>..."
L16_1.m_Talk_ENG = L17_1
L17_1 = "業界稱之為<color=#ffd34c>手榴彈製造機</color> 的戰術指揮而聞名……"
L16_1.m_Talk_TWN = L17_1
L17_1 = "หรือที่คนในวงการเรียกว่า <color=#ffd34c>\"วิ่งเข้าหาระเบิด\"</color>…"
L16_1.m_Talk_THA = L17_1
L17_1 = "Vốn được các lão làng khác trong ngành gọi là phong cách <color=#ffd34c>\"tùy hứng\"</color>..."
L16_1.m_Talk_VTN = L17_1
L17_1 = "业界称之为<color=#ffd34c>手榴弹制造机</color> 的战术指挥而闻名……"
L16_1.m_Talk_SCN = L17_1
L17_1 = "… den einige in der Branche als <color=#ffd34c>selbstmörderisch</color> bezeichneten …"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Que les gens de l'industrie qualifient de <color=#ffd34c>« mortifère »</color>..."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "EP1_ACT1_STAGE4_END@117#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 14
L17_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L17_1.m_Pos = "C"
L18_1 = "아무리 신규 대원을 구인해 봐야 미나 양 같은 호구......"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "新規隊員を募ったところで、ミナさんみたいな世間知らず……"
L17_1.m_Talk_JPN = L18_1
L18_1 = "We were hard pressed to find new recruits. At best, only suckers like Mina..."
L17_1.m_Talk_ENG = L18_1
L18_1 = "所以現在無論怎麼招募新隊員，也只有米娜小姐這樣的冤大頭……"
L17_1.m_Talk_TWN = L18_1
L18_1 = "เราก็เลยเจอปัญหาหนักในการหาพนักงานใหม่ อย่างดีที่สุดที่พอจะหาได้ก็คือพวกหลอกง่ายอย่างมีนา..."
L17_1.m_Talk_THA = L18_1
L18_1 = "Bọn tôi rất vất vả để tuyển người mới. Những người tốt nhất, thì cũng khờ khạo như Mina..."
L17_1.m_Talk_VTN = L18_1
L18_1 = "所以现在无论怎么招新队员，也只有米娜小姐这样的冤大头……"
L17_1.m_Talk_SCN = L18_1
L18_1 = "… hatten wir Mühe, neue Rekruten zu finden. Bestenfalls haben sich nur Knalltüten wie Mina …"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Nous avons eu beaucoup de mal à trouver de nouvelles recrues. Des petits joueurs comme Mina, tout au plus..."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "EP1_ACT1_STAGE4_END@118#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 14
L18_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
