L18_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L18_1.m_Pos = "C"
L19_1 = "아니, 업계 신입이 아니면 거들떠 보지도 않는 상황이었죠."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "いえ、業界新人でもないかぎり、見向きもされない状況だったのです。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Uh, I mean, rookies who didn't know much about the industry bothered to apply."
L18_1.m_Talk_ENG = L19_1
L19_1 = "咳咳，我是說也只有米娜小姐這樣的業界新人會加入我們小隊。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "เอ่อ ฉันหมายถึง เด็กใหม่ที่ไม่ค่อยรู้ประสีประสาในวงการ แต่ก็ยังใจถึงพอที่จะสมัครงานน่ะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Uh, ý tôi là, những tân binh không biết nhiều về ngành mà vẫn nộp đơn ấy."
L18_1.m_Talk_VTN = L19_1
L19_1 = "咳咳……我是说只有米娜小姐这样的业界新人会加入我们小队。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "… äh, ich meine, Frischlinge, die sich in der Branche nicht auskannten, beworben."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Enfin, je veux dire que seuls des bleus qui ne connaissaient pas grand-chose à cette industrie ont pris la peine de postuler."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "EP1_ACT1_STAGE4_END@119#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 119
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 14
L19_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L19_1.m_Pos = "C"
L20_1 = "그런고로 저희 회사에서 가용한 카운터 요원은 주시윤 군 달랑 한 명만 남게 되었습니다."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "そんなわけで、わが社でまわせるカウンター要員は、アキヤマ君たった一人になりました。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "With that, Shiyoon was the only Counter left in our company."
L19_1.m_Talk_ENG = L20_1
L20_1 = "因此本公司可以出動的制裁者就只剩下周時雲一人。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ด้วยสาเหตุนี้ บริษัทก็เลยเหลือชิยุนเป็นเคาน์เตอร์เพียงคนเดียว"
L19_1.m_Talk_THA = L20_1
L20_1 = "Và cứ thế, Shiyoon trở thành Counter duy nhất còn sót lại trong công ty."
L19_1.m_Talk_VTN = L20_1
L20_1 = "因此，本公司可以出动的制裁者就只剩下周时云一人。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Damit war Shiyoon der einzige verbliebene Counter in unserem Unternehmen."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Et du coup, Charles était le seul Counter encore présent dans l'entreprise."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
