L22_1 = "UNIT_LAUGH"
L21_1.m_Face = L22_1
L21_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L21_1.m_Pos = "C"
L22_1 = "물론 시윤 군의 카운터 적성이야 아주 뛰어납니다."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "もちろん、アキヤマ君はカウンターとして非常に優れた人材です。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Of course, Shiyoon possesses remarkable aptitude as a Counter."
L21_1.m_Talk_ENG = L22_1
L22_1 = "當然時雲君是非常優秀的制裁者。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "แน่นอนว่าชิยุนเป็นเคาน์เตอร์ที่มีความสามารถโดดเด่น"
L21_1.m_Talk_THA = L22_1
L22_1 = "Tất nhiên, Shiyoon sở hữu năng lực vượt trội để trở thành Counter."
L21_1.m_Talk_VTN = L22_1
L22_1 = "当然时云君是非常出色的制裁者。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Klar, Shiyoon verfügt über bemerkenswerte Talente als Counter."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Bien sûr, Charles possède de formidables aptitudes en tant que Counter."
L21_1.m_Talk_FRA = L22_1
