L22_1.m_Pos = "C"
L23_1 = "하지만 스승님도 알다시피 그 "
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "ただ、師匠もよーくご存じのように、あの "
L22_1.m_Talk_JPN = L23_1
L23_1 = "But as you're well aware... "
L22_1.m_Talk_ENG = L23_1
L23_1 = "但師父也知道，"
L22_1.m_Talk_TWN = L23_1
L23_1 = "แต่อย่างที่รู้กันอยู่... "
L22_1.m_Talk_THA = L23_1
L23_1 = "Nhưng như người biết rõ... "
L22_1.m_Talk_VTN = L23_1
L23_1 = "老师肯定也是知道的。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Aber was soll ich sagen? "
L22_1.m_Talk_DEU = L23_1
L23_1 = "Mais comme vous le savez bien... "
L22_1.m_Talk_FRA = L23_1
