L25_1 = " 군이라서요."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "m_bTalkAppend"
L24_1[L25_1] = true
L25_1 = "のことですからね。"
L24_1.m_Talk_JPN = L25_1
L25_1 = " I don't think I need to elaborate much further..."
L24_1.m_Talk_ENG = L25_1
L25_1 = "周、時、雲。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ฉันคงไม่ต้องขยายความมากไปกว่านี้ใช่มั้ยคะ..."
L24_1.m_Talk_THA = L25_1
L25_1 = "Tôi nghĩ là mình không cần phải giải thích nhiều hơn nữa..."
L24_1.m_Talk_VTN = L25_1
L25_1 = "周、时、云！"
L24_1.m_Talk_SCN = L25_1
L25_1 = " Ich denke, das muss ich nicht weiter ausführen."
L24_1.m_Talk_DEU = L25_1
L25_1 = " Je ne pense pas avoir besoin d'en dire plus..."
L24_1.m_Talk_FRA = L25_1
