L26_1 = "EP1_ACT1_STAGE4_END@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 14
L25_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
