L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L25_1.m_Pos = "C"
L26_1 = "같이 작전 나간 대원들마다 보고서 대신 사직서가 올라오더군요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "いっしょに作戦に出た隊員たちから、報告書の代わりに退職願があがってきて……"
L25_1.m_Talk_JPN = L26_1
L26_1 = "But everyone who went into combat with him would submit a resignation letter instead of a mission report."
L25_1.m_Talk_ENG = L26_1
L26_1 = "每次他與其他隊員一起外出作戰後，我從其他隊員那裡收到的不是報告書，而是辭職書。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ทุกคนที่ออกรบกับเขา พอกลับมา แทนที่จะส่งรายงานภารกิจ ก็ยื่นจดหมายลาออกกันทุกคน"
L25_1.m_Talk_THA = L26_1
L26_1 = "Nhưng tất cả những người từng tham gia chiến đấu với cậu ấy toàn gửi đơn từ chức thay vì báo cáo nhiệm vụ."
L25_1.m_Talk_VTN = L26_1
L26_1 = "每次他与其他队员一起外出作战后，我从其他队员那里收到的都不是报告书而是辞职信。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Aber Leute, die mit ihm in den Kampf zogen, reichten hinterher statt eines Einsatzberichts lieber Kündigungsschreiben ein."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Tous ceux qui sont partis en mission avec lui ont soumis une lettre de démission en guise de rapport à leur retour."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP1_ACT1_STAGE4_END@126#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 14
