L26_1.m_Pos = "C"
L27_1 = "참고로 사내 VPN에 보시면 <color=#ffd34c>주시윤 사건/사고</color> 전용 게시판도 있습니다."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "ちなみに、社内VPNには<color=#ffd34c>アキヤマ関連事件/事故</color> 専用コミュニティまで立ち上がっていますよ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "If you look at the company VPN, there's an entire forum dedicated to <color=#ffd34c>Joo Shiyoon Cases/Incidents</color>."
L26_1.m_Talk_ENG = L27_1
L27_1 = "打開公司的內部網路，還能看到名為<color=#ffd34c>周時雲事件/事故</color>的專欄。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ถ้าคุณเข้า VPN ของบริษัท ก็จะเห็นคนตั้งฟอรัมสำหรับ<color=#ffd34c>คดี/ปัญหาเกี่ยวกับชิยุน</color>โดยเฉพาะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Nếu người nhìn vào VPN của công ty, có cả một diễn đàn dành riêng cho <color=#ffd34c>Trường hợp/Sự cố Joo Shiyoon</color> luôn đấy."
L26_1.m_Talk_VTN = L27_1
L27_1 = "打开公司内部专用网络，还能看到名为<color=#ffd34c>周时云事件/事故</color>的专栏。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Im VPN des Unternehmens gibt es ein ganzes Forum, das <color=#ffd34c>Vorfällen mit Joo Shiyoon</color> gewidmet ist."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Si vous regardez sur le réseau de l'entreprise, il y a un forum entier consacré aux <color=#ffd34c>affaires et incidents de Charles Joo</color>."
L26_1.m_Talk_FRA = L27_1
