L30_1 = "UNIT_LAUGH"
L29_1.m_Face = L30_1
L30_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "L"
L30_1 = "하하. 칭찬을 들으니 좀 쑥쓰럽네요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "ハハッ、そんなに褒められると照れちゃいます。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Haha. Aww, it's nothing. You're too kind."
L29_1.m_Talk_ENG = L30_1
L30_1 = "哈哈，聽到別人的誇獎，我有點不好意思了呢。 "
L29_1.m_Talk_TWN = L30_1
L30_1 = "ฮ่าฮ่า ก็ไม่เท่าไหร่หรอกครับ คุณน่ะชมเกินไปแล้ว"
L29_1.m_Talk_THA = L30_1
L30_1 = "Haha. Ờ thì có gì đâu mà. Thật là tử tế quá."
L29_1.m_Talk_VTN = L30_1
L30_1 = "哈哈，多谢夸奖，还有些害羞呢。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Ach, nicht der Rede wert … Aber sehr nett, dass du es erwähnst."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Ha ha. Oh, ce n'est rien. Vous êtes trop gentille."
L29_1.m_Talk_FRA = L30_1
