L31_1 = "……絶対褒め言葉じゃない。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Trust me, it's not a compliment."
L30_1.m_Talk_ENG = L31_1
L31_1 = "……這絕對不是誇獎吧。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ฉันว่าเธอไม่ได้ชมนายนะ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tin tôi đi, đó không phải là lời khen đâu."
L30_1.m_Talk_VTN = L31_1
L31_1 = "……这绝对不是夸奖吧。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Glaub mir, das ist kein Kompliment."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Crois-moi, ce n'est pas un compliment."
L30_1.m_Talk_FRA = L31_1
