L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 14
L32_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "UNIT_LAUGH"
L32_1.m_Face = L33_1
L32_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "덕분에 이터니움 채굴은 고사하고 아예 부대 편성을 못 할 상황이라,"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "おかげさまで、エタニウム採掘はおろか、部隊編成すらできない状況なので、"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Thanks to this, we couldn't even put a tactical team together, let alone mine for Eternium."
L32_1.m_Talk_ENG = L33_1
L33_1 = "多虧了他，公司別說是挖掘永恆之金了，連組織一個小隊都沒辦法。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เพราะแบบนี้ เราก็เลยตั้งทีมยุทธวิธีขึ้นมาไม่ได้สักที ดังนั้นเรื่องขุดอีเทอร์เนียมนี่ลืมไปได้เลย"
L32_1.m_Talk_THA = L33_1
L33_1 = "Vì thế, chúng ta thậm chí còn không thể kết hợp một đội tác chiến lại với nhau, chứ đừng nói đến việc khai thác Vàng Vĩnh Cửu."
L32_1.m_Talk_VTN = L33_1
L33_1 = "多亏了他，别说是挖掘能晶了，就连组建一个小队都没办法。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Aus diesen Gründen konnten wir nicht mal ein taktisches Team zusammenstellen – geschweige denn ein Team für den Eterniumabbau."
L32_1.m_Talk_DEU = L33_1
L33_1 = "À cause de tout ça, nous n'avons même pas pu constituer une équipe tactique, et encore moins récolter de l'éternium."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "EP1_ACT1_STAGE4_END@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 14
L33_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L33_1.m_Pos = "C"
L34_1 = "당연히 기존 계약들은 다 끊겼습니다."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "とうぜん既存の契約はすべて切られてしまいました。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Naturally, we lost all our contracts."
L33_1.m_Talk_ENG = L34_1
L34_1 = "我們手上的契約自然都解除了。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "แน่นอนว่าเราเสียสัญญาจ้างไปทั้งหมด"
L33_1.m_Talk_THA = L34_1
L34_1 = "Lẽ đương nhiên, chúng ta mất tất cả hợp đồng."
L33_1.m_Talk_VTN = L34_1
L34_1 = "签过的合同自然也都解除了。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Und infolgedessen haben wir all unsere Verträge verloren."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Naturellement, nous avons perdu tous nos contrats."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP1_ACT1_STAGE4_END@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 14
L34_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L34_1.m_Pos = "C"
L35_1 = "물론 계약 파기에 따른 각종 위약금도 물어야 했죠."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "もちろん、契約破棄による様々な違約金まで払うハメになりましたね。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "You can probably imagine the contract termination fees we had to pay."
L34_1.m_Talk_ENG = L35_1
L35_1 = "當然，解除契約的話，公司就必須支付隨之而來各樣的違約金。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "คุณคงนึกภาพออก ว่าเราต้องเสียค่าปรับในการบอกเลิกสัญญาจ้างเยอะแค่ไหน"
L34_1.m_Talk_THA = L35_1
L35_1 = "Người có thể tưởng tượng ra số tiền bồi thường chấm dứt hợp đồng mà chúng ta phải trả rồi đó."
L34_1.m_Talk_VTN = L35_1
L35_1 = "当然，解除合同的话，公司就必须支付随之而来各样的违约金。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Ihr könnt euch vielleicht vorstellen, was uns die Vertragsauflösungen an Gebühren gekostet haben."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Je vous laisse imaginer les frais de rupture de contrat que nous avons dû payer."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP1_ACT1_STAGE4_END@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 14
L35_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "UNIT_HATE"
L35_1.m_Face = L36_1
L35_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L35_1.m_Pos = "C"
L36_1 = "음...... 아니, 그...... 뭐랄까......"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "うん……、いや、なんていうか……"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Um... So... I mean..."
L35_1.m_Talk_ENG = L36_1
L36_1 = "呃……這個……怎麼說呢……"
L35_1.m_Talk_TWN = L36_1
L36_1 = "เอ่อ... ถ้าอย่างนั้น... คือว่า..."
L35_1.m_Talk_THA = L36_1
L36_1 = "Ừm... Vậy là... Ý ta là..."
L35_1.m_Talk_VTN = L36_1
L36_1 = "嗯……这个……怎么说呢……"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Äh … Also … Ich meine …"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Euh... Donc... Enfin..."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP1_ACT1_STAGE4_END@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 14
L36_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "UNIT_LAUGH"
L36_1.m_Face = L37_1
L36_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L36_1.m_Pos = "C"
L37_1 = "결국 좋은 계약들은 경쟁업체들에게 다 빼앗기고,"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "結局、優良契約はすべて競合他社にとられ、"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Our competitors jumped at the opportunity to steal all our good contracts away."
L36_1.m_Talk_ENG = L37_1
L37_1 = "但好契約最後都被競爭對手搶走了。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "คู่แข่งของเราใช้โอกาสนี้แย่งงานดีๆ จากเราไปจนหมด"
L36_1.m_Talk_THA = L37_1
L37_1 = "Các đối thủ cạnh tranh đã chớp cơ hội và lấy đi tất cả các hợp đồng tốt của chúng ta."
L36_1.m_Talk_VTN = L37_1
L37_1 = "好合同最后都被竞争对手抢走了，"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Unsere Konkurrenten nutzten die Gelegenheit, um uns alle guten Verträge wegzuschnappen."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Nos concurrents ont sauté sur l'occasion pour nous voler tous les bons contrats."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP1_ACT1_STAGE4_END@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 14
L37_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L37_1.m_Pos = "C"
L38_1 = "그나마 남은 건 극히 위험하고 보수도 짠 정크들뿐이었죠."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "なんとか残った契約は、極めて危険な案件で報酬は弾まないゴミばかり。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "All we had left were junk jobs that were extremely dangerous but paid like crap."
L37_1.m_Talk_ENG = L38_1
L38_1 = "剩下的都是些特別危險，報酬又少的案子。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เหลืออยู่ก็แค่งานห่วยๆ ที่อันตรายสุดๆ แต่ได้ค่าจ้างนิดเดียว"
L37_1.m_Talk_THA = L38_1
L38_1 = "Tất cả những gì còn lại là những công việc rác rưởi vô cùng nguy hiểm nhưng được trả công rất tào lao."
L37_1.m_Talk_VTN = L38_1
L38_1 = "剩下的都是些特别危险，报酬又少的单子。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Wir hatten nur noch schlechte Jobs, die extrem gefährlich waren und miserabel bezahlt wurden."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Tout ce qui nous restait c'était les boulots pourris, extrêmement dangereux et très mal payés."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "EP1_ACT1_STAGE4_END@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 14
L38_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L38_1.m_Pos = "C"
L39_1 = "제대로 된 카운터 요원도 없이 무리하게 위험임무만 골라서 하다 보니......"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "まともなカウンター要員もいない状況で、危険な任務ばかり強引にやっていたので、"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Since we were only taking on dangerous missions without any competent Counters..."
L38_1.m_Talk_ENG = L39_1
L39_1 = "我們沒有像樣的制裁者，加上又只能勉強挑一些危險任務……"
L38_1.m_Talk_TWN = L39_1
L39_1 = "แล้วพอเราทำแต่ภารกิจอันตรายโดยไม่มีเคาน์เตอร์เก่งๆ..."
L38_1.m_Talk_THA = L39_1
L39_1 = "Vì chúng ta chỉ tham gia vào các nhiệm vụ nguy hiểm mà không có Counter nào có đủ trình độ..."
L38_1.m_Talk_VTN = L39_1
L39_1 = "我们没有像样的制裁者，加上又只能挑一些危险任务，"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Da wir nur noch gefährliche Missionen ohne kompetente Counter annahmen …"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Comme nous n'acceptions que des missions dangereuses sans aucun Counter compétent..."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "EP1_ACT1_STAGE4_END@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 14
L39_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L39_1.m_Pos = "C"
L40_1 = "전투함들은 모조리 박살이 나서 고철로 밖에는 쓸데가 없고,"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "戦闘艦船はすべてボロボロになって、くず鉄同然……"
L39_1.m_Talk_JPN = L40_1
L40_1 = "All our battleships were eventually destroyed and reduced to scrap metal."
L39_1.m_Talk_ENG = L40_1
L40_1 = "所以戰艦全變成了沒用的廢鐵，"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ยานรบของเราก็ค่อยๆ พังไปทีละลำ จนต้องขายเป็นเศษเหล็ก"
L39_1.m_Talk_THA = L40_1
L40_1 = "Tất cả các tàu chiến rốt cuộc cũng bị phá hủy và biến thành kim loại phế liệu."
L39_1.m_Talk_VTN = L40_1
L40_1 = "所以战舰全成了没用的废铁，"
L39_1.m_Talk_SCN = L40_1
L40_1 = "… wurden all unsere Kriegsschiffe zerstört und schließlich verschrottet."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Tous nos vaisseaux ont finalement été détruits et réduits à l'état d'épaves."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "EP1_ACT1_STAGE4_END@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 14
L40_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L40_1.m_Pos = "C"
L41_1 = "용병들 위험 수당은 몇 배로 오른 데다가,"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "しかも、傭兵への危険手当も数倍に跳ね上がる始末で、"
L40_1.m_Talk_JPN = L41_1
L41_1 = "We also had to give extra hazard pay to the mercenaries..."
L40_1.m_Talk_ENG = L41_1
L41_1 = "然後又因為任務過於危險，傭兵的薪水漲了好幾倍，"
L40_1.m_Talk_TWN = L41_1
L41_1 = "แถมเรายังต้องจ่ายค่าเสี่ยงอันตรายให้กับทหารรับจ้าง..."
L40_1.m_Talk_THA = L41_1
L41_1 = "Chúng ta cũng phải trả thêm tiền trợ cấp nguy hiểm cho đám Lính Đánh Thuê..."
L40_1.m_Talk_VTN = L41_1
L41_1 = "然后又因为任务过于危险，佣兵的工资涨了好几倍，"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Außerdem mussten wir den Söldnern eine zusätzliche Gefahrenzulage zahlen."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Nous avons également dû payer des primes de risques supplémentaires aux mercenaires..."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP1_ACT1_STAGE4_END@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 14
L41_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L41_1.m_Pos = "C"
L42_1 = "이제는 보험사에서도 받아 주는 데가 없습니다."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "もはや保険会社からも門前払いです。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "And now there's not a single insurance company that will cover us."
L41_1.m_Talk_ENG = L42_1
L42_1 = "現在連保險公司都不讓我們投保了。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ตอนนี้ไม่มีบริษัทประกันไหนกล้ารับประกันให้เราแล้วล่ะค่ะ"
L41_1.m_Talk_THA = L42_1
L42_1 = "Và giờ thì không có một công ty bảo hiểm nào dám chi trả cho chúng ta nữa."
L41_1.m_Talk_VTN = L42_1
L42_1 = "现在连保险公司都不让我们投保了。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Und mittlerweile gibt es keine einzige Versicherungsgesellschaft mehr, die bereit wäre, für uns aufzukommen."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Et maintenant, plus une seule compagnie d'assurance ne souhaite nous couvrir."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
