L3_1 = "UNIT_LAUGH"
L2_1.m_Face = L3_1
L2_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L2_1.m_Pos = "L"
L3_1 = "역시 스승님."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "さすが、師匠。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "This is why I respect you, Master."
L2_1.m_Talk_ENG = L3_1
L3_1 = "不愧是師父。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "นี่คือเหตุผลที่ฉันเคารพคุณล่ะ อาจารย์"
L2_1.m_Talk_THA = L3_1
L3_1 = "Đó là lý do tại sao tôi tôn trọng người đấy, Sếp ạ."
L2_1.m_Talk_VTN = L3_1
L3_1 = "不愧是老师，"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Deshalb respektiere ich dich, Meisterin."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Voilà la raison pour laquelle je vous respecte, maître."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "EP1_ACT1_STAGE4_END@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 14
L3_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L3_1.m_Pos = "L"
L4_1 = "그래도 낯짝이 있다는 점에서 어떤 불민한 제자보다는 나은 점이 있으시군요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "まだ良心があるところは、あの失敬な弟子よりマシですね。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "At least you know when to apologize, unlike that dim-witted apprentice of yours."
L3_1.m_Talk_ENG = L4_1
L4_1 = "在要不要臉這方面，還是比某些愚鈍的徒弟好很多。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "อย่างน้อยคุณก็รู้ว่าเวลาไหนควรขอโทษ ไม่เหมือนลูกศิษย์ซื่อบื้อของคุณ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Ít nhất thì người cũng biết khi nào nên xin lỗi, không giống như đồ đệ của người."
L3_1.m_Talk_VTN = L4_1
L4_1 = "在要不要脸这个问题上，还是要比某些愚钝的徒弟好很多。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Du weißt wenigstens, wann man sich entschuldigen muss – im Gegensatz zu deinem dämlichen Lehrling."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Au moins, vous savez à quel moment présenter vos excuses, contrairement à votre imbécile d'apprenti."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "EP1_ACT1_STAGE4_END@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 14
L4_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "UNIT_LAUGH"
L4_1.m_Face = L5_1
L5_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "R"
L5_1 = "하하, 언제나 스승님껜 배울 점이 남아 있지요."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "ハハ、師匠にはいつも学ばせていただいてます。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Haha! I still have much to learn from you."
L4_1.m_Talk_ENG = L5_1
L5_1 = "哈哈，師父不管什麼時候，都有很多值得我學習的地方呢。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ฮะฮะ! ผมยังต้องเรียนรู้จากอาจารย์อีกมากครับ"
L4_1.m_Talk_THA = L5_1
L5_1 = "Haha! Tôi vẫn phải học hỏi nhiều lắm."
L4_1.m_Talk_VTN = L5_1
L5_1 = "哈哈，老师不管什么时候都有很多值得我学习的地方呢。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Haha, ich muss wohl noch viel von dir lernen …"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Ha ha ! J'ai encore tellement à apprendre de vous."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "EP1_ACT1_STAGE4_END@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 14
L5_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L5_1.m_Pos = "L"
L6_1 = "물론 전혀 도움이 되지 않는다는 점에서 둘 다 별 차이는 없는 것 같지만요."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "今さら改心したところで役に立たないのは、二人とも大差ないですけどね。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "But of course, the fact that both of you are equally useless remains the same."
L5_1.m_Talk_ENG = L6_1
L6_1 = "當然，兩位在完全幫不上忙這點倒是沒什麼兩樣。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "แต่แน่นอน เรื่องที่ว่าพวกคุณทั้งคู่ไร้ประโยชน์พอๆ กัน ก็ยังเป็นความจริง"
L5_1.m_Talk_THA = L6_1
L6_1 = "Nhưng tất nhiên, sự thật vẫn là cả hai người đều vô dụng như nhau."
L5_1.m_Talk_VTN = L6_1
L6_1 = "当然，两位在完全帮不上忙这点上没什么两样。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Nichtsdestotrotz bleibt die Tatsache bestehen, dass ihr beide gleichermaßen nutzlos seid."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Mais bien sûr, cela ne change rien au fait que vous êtes tous les deux parfaitement inutiles."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
