L9_1 = "EP1_ACT1_STAGE4_END@158#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 158
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 14
L8_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L8_1.m_Pos = "L"
L9_1 = "어쨌든 딱 두 달 전부터 월급도 밀리고 금융권 채무 이자도 갚지 못한 상황입니다."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "とにかく、ちょうど2か月前から、賃金支払もローンの利子返済も滞っている状況です。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Anyway, we're already two months behind in our interest payments, as well as wages for our employees."
L8_1.m_Talk_ENG = L9_1
L9_1 = "總之，公司已經拖欠了兩個月的薪水，也無法償還金融機關的利息。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ในตอนนี้ เราค้างจ่ายดอกเบี้ยเงินกู้ และค้างเงินเดือนพนักงานมา 2 เดือนแล้ว"
L8_1.m_Talk_THA = L9_1
L9_1 = "Dù gì thì chúng ta cũng đã trả lãi chậm hai tháng rồi, tiền lương cho nhân viên cũng thế."
L8_1.m_Talk_VTN = L9_1
L9_1 = "总之，公司已拖欠了两个月的工资，又还不上金融债券利息，"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Wie dem auch sei, wir sind bereits zwei Monate mit unseren Zinszahlungen im Rückstand, ebenso wie mit den Gehaltszahlungen an unsere Mitarbeiter."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Quoi qu'il en soit, nous avons déjà deux mois de retard sur le paiement de notre emprunt ainsi que sur le salaire des employés."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
