L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L9_1.m_Pos = "L"
L10_1 = "이 고물 배라도 팔지 않으면 꼼짝없이 부도처리 해야 할 판이었는데...... "
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "このボロ船でも売らなければ、打つ手なく倒産するところだったのですが…… 。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "We were on the verge of total bankruptcy. We almost had to sell off this trashy ship too, until.. "
L9_1.m_Talk_ENG = L10_1
L10_1 = "為了避免破產，差點連這艘舊船都賣掉了。然而就在這個時候——"
L9_1.m_Talk_TWN = L10_1
L10_1 = "เรากำลังจะล้มละลายแบบกู่ไม่กลับ เกือบจะต้องขายยานห่วยๆ ลำนี้ด้วย แต่แล้ว.. "
L9_1.m_Talk_THA = L10_1
L10_1 = "Chúng ta đang trên bờ vực phá sản. Chúng ta gần như đã phải bán hết đám tàu bè rác rưởi này, cho đến khi..."
L9_1.m_Talk_VTN = L10_1
L10_1 = "为了不至于破产，差点儿连这艘旧船都卖掉了。然而就在这个时候，"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Wir waren am Rande des totalen Bankrotts und hätten fast auch dieses Schrottschiff verkaufen müssen, bis … "
L9_1.m_Talk_DEU = L10_1
L10_1 = "Nous étions au bord de la faillite. J'ai même failli vendre ce vaisseau pourri, jusqu'à... "
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
