L11_1 = 100
L10_1.m_Crash = L11_1
L11_1 = "짜잔~! 구세주처럼 내가 등장했지."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "じゃじゃーん！　救世主のように私が現れたのだ。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Tada! I appeared and saved the day!"
L10_1.m_Talk_ENG = L11_1
L11_1 = "鏘鏘~！我們的救世主登場啦。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "แถ่นแท้น! ฉันก็ปรากฏตัวขึ้น เพื่อช่วยทุกคนเอาไว้!"
L10_1.m_Talk_THA = L11_1
L11_1 = "Tada! Ta xuất hiện và cứu rỗi tất cả mọi người!"
L10_1.m_Talk_VTN = L11_1
L11_1 = "锵锵~！我们的救世主登场啦。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Tada! Ich bin erschienen und zum Helden geworden!"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Tada ! Je suis arrivé et j'ai sauvé le coup !"
L10_1.m_Talk_FRA = L11_1
