L15_1 = "UNIT_SERIOUS"
L14_1.m_Face = L15_1
L14_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L14_1.m_Pos = "C"
L14_1.m_Crash = 50
L15_1 = "난 이런 이야기를 들은 적이 없다고!"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "私はこんな話、いっさい聞いてないんだけど！"
L14_1.m_Talk_JPN = L15_1
L15_1 = "I never heard anything about this!"
L14_1.m_Talk_ENG = L15_1
L15_1 = "我可沒聽說過這種事！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ฉันไม่เห็นจะรู้เรื่องพวกนี้มาก่อนเลย!"
L14_1.m_Talk_THA = L15_1
L15_1 = "Tôi chưa bao giờ nghe thấy những việc này!"
L14_1.m_Talk_VTN = L15_1
L15_1 = "我可没听说过这种事！"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Davon ist mir noch nichts zu Ohren gekommen!"
L14_1.m_Talk_DEU = L15_1
L15_1 = "On ne m'avait jamais parlé de tout ça !"
L14_1.m_Talk_FRA = L15_1
