L16_1 = "EP1_ACT1_STAGE4_END@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 14
L15_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L15_1.m_Pos = "C"
L15_1.m_Crash = 20
L16_1 = "오늘 입사해서 야간 임무까지 구르고 왔는데 회사가 부도라니?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "今日入社して夜間の任務までこなしてきたのに、会社が倒産？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "I literally got hired today and worked overtime... And now you're telling me the company's bankrupt?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "我今天才剛進公司，而且還加班接任務，結果妳跟我說公司破產了？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ฉันเพิ่งเข้าทำงานวันนี้วันแรก แถมยังต้องทำโอทีอีก... แล้วตอนนี้คุณก็มาบอกว่าบริษัทล้มละลาย?"
L15_1.m_Talk_THA = L16_1
L16_1 = "Tôi mới được thuê vào và phải làm thêm giờ ngày hôm nay... Và bây giờ các người đang nói với tôi là công ty này đã phá sản ư?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "我今天刚进公司，甚至还加班接任务，结果你和我说公司破产了？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ich wurde erst heute eingestellt und habe Überstunden gemacht – und jetzt höre ich, dass das Unternehmen bankrott ist?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Je viens tout juste d'arriver aujourd'hui et j'ai déjà fait des heures supplémentaires... Et maintenant vous me dites que l'entreprise est en faillite ?"
L15_1.m_Talk_FRA = L16_1
