L24_1 = "신임 사장님께서 저희 회사의 채무를 모두 인수하셨거든요."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "新社長がわが社の債権をすべて買い取りましたから。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Our new president has acquired all of the company's debts."
L23_1.m_Talk_ENG = L24_1
L24_1 = "新任老闆已經攬下了本公司所有的債務。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ประธานคนใหม่ของเราชดใช้หนี้ของบริษัททั้งหมดให้แล้ว"
L23_1.m_Talk_THA = L24_1
L24_1 = "Chủ tịch mới của chúng ta đã xử lý tất cả các khoản nợ của công ty rồi."
L23_1.m_Talk_VTN = L24_1
L24_1 = "新任老板已接手了本公司所有的债务，"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Unser neuer Vorsitzender hat auch alle Schulden des Unternehmens übernommen."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Notre nouveau président a racheté toutes les dettes de l'entreprise."
L23_1.m_Talk_FRA = L24_1
