L25_1 = "短時間內不需要擔心資金的問題。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "เรื่องเงินไม่ใช่ปัญหาของเราอีกต่อไป เฉพาะในตอนนี้น่ะนะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Bây giờ chúng ta sẽ không còn phải lo lắng về tiền bạc nữa."
L24_1.m_Talk_VTN = L25_1
L25_1 = "短时间内不需要担心资金的问题。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Wir müssen uns vorerst keine Geldsorgen machen."
L24_1.m_Talk_DEU = L25_1
L25_1 = "L'argent n'est plus un problème, pour le moment."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "EP1_ACT1_STAGE4_END@175#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 175
L25_1.m_CutScenProcessKey = L26_1
