L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L25_1.m_Pos = "L"
L26_1 = "정말이지 사장님은 천사같이 자비로우신 분이죠."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "社長はじつに天使のように慈悲に満ちたお方で……"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Our president is like an angel! Full of compassion and mercy..."
L25_1.m_Talk_ENG = L26_1
L26_1 = "老闆大人真的就像天使一樣慈悲呢。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ท่านประธานของเราก็เหมือนกับเทวดามาโปรด! เปี่ยมด้วยความเมตตาและกรุณา..."
L25_1.m_Talk_THA = L26_1
L26_1 = "Chủ tịch cũng giống như một thiên thần vậy! Đầy lòng trắc ẩn và thương xót..."
L25_1.m_Talk_VTN = L26_1
L26_1 = "老板大人真的像天使一样慈悲善良啊。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Unser Vorsitzender ist voller Mitgefühl und Barmherzigkeit – wie ein Engel."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Notre président est un ange ! Il n'est que compassion et miséricorde..."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
