L27_1.m_Crash = L28_1
L28_1 = "이건 기계잖아?!"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "これはどう見ても立派な機械でしょ！？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "It's still a machine!"
L27_1.m_Talk_ENG = L28_1
L28_1 = "這東西不是機器人嗎？！"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ยังไงมันก็ยังเป็นแค่หุ่นยนต์!"
L27_1.m_Talk_THA = L28_1
L28_1 = "Nó vẫn là một cái máy!"
L27_1.m_Talk_VTN = L28_1
L28_1 = "这玩意儿不是机器吗？！"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Er ist immer noch eine Maschine!"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Ça reste une machine !"
