L29_1 = "UNIT_SERIOUS"
L28_1.m_Face = L29_1
L28_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L28_1.m_Pos = "L"
L29_1 = "무슨 상관이죠?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "それがどうしたんです？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Who cares?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "那又怎麼樣？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ใครจะไปสนเรื่องนั้นกันล่ะคะ?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Ai quan tâm chứ?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "那又怎么样？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Das spielt keine Rolle!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Et alors ?"
