L30_1 = "EP1_ACT1_STAGE4_END@179#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 179
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 14
L29_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L29_1.m_Pos = "L"
L30_1 = "전 돈만 준다면 기계가 아니라 짚신벌레라도 사장으로 모실 생각이 있습니다만."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "お金さえくれれば、私はゾウリムシでも仕えます。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I'd be happy to serve anyone or anything as my boss, as long as they've got the money..."
L29_1.m_Talk_ENG = L30_1
L30_1 = "只要給錢，別說是機器人了，就是草履蟲我也會把它當成老闆。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ฉันยินดีรับใช้ทุกคน หรือจะเป็นอะไรก็ได้ ตราบใดที่พวกเขามีเงิน..."
L29_1.m_Talk_THA = L30_1
L30_1 = "Tôi sẽ vui mừng phục vụ bất cứ ai hoặc bất cứ thứ gì làm Ông Chủ của mình, miễn là họ có tiền..."
L29_1.m_Talk_VTN = L30_1
L30_1 = "只要给钱，别说是机器了，就是毛毛虫我也会把它当成老板。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Es ist doch egal, wer oder was der Chef ist, solange er das Geld hat."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Du moment qu'il a de l'argent, je serai ravie de travailler pour un nouveau patron, peu importe qui il est ou ce qu'il est..."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
