L32_1 = "UNIT_LAUGH"
L31_1.m_Face = L32_1
L31_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L31_1.m_Pos = "L"
L32_1 = "말씀이 없으시니 납득하신 걸로 알겠습니다. "
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "お話は済んだようですから、納得されたとみなしますね。 "
L31_1.m_Talk_JPN = L32_1
L32_1 = "I'll take your silence as consent. "
L31_1.m_Talk_ENG = L32_1
L32_1 = "看您不說話，我想您應該已經理解公司的現狀了吧。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ถ้าเงียบแบบนั้น ฉันถือว่าคุณยอมรับก็แล้วกันนะคะ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tôi sẽ xem sự im lặng của người là đồng ý. "
L31_1.m_Talk_VTN = L32_1
L32_1 = "看你不说话，我想你应该理解公司的现状了吧。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ich werte dein Schweigen als Zustimmung. "
L31_1.m_Talk_DEU = L32_1
L32_1 = "Je prends votre silence comme un signe de consentement. "
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP1_ACT1_STAGE4_END@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 14
L32_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L32_1.m_Pos = "L"
L33_1 = "어쨌든 자금 문제도 해결되고 신규 카운터 요원도 충원했고 스승님까지 돌아왔으니,"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "これで資金問題も解決して、新規カウンター要員も加わり、師匠も戻られたと。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Anyway, now that we've solved our financial issues, hired a new Counter, and even got you back,"
L32_1.m_Talk_ENG = L33_1
L33_1 = "總之，資金問題已經解決了，又有了新的制裁者，而且師父也回來了。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เอาล่ะ ตอนนี้เราแก้ปัญหาเรื่องเงินเรียบร้อยแล้ว จ้างเคาน์เตอร์คนใหม่มาได้คนนึง แถมยังได้อาจารย์กลับมาอีก"
L32_1.m_Talk_THA = L33_1
L33_1 = "Dù sao đi nữa, bây giờ chúng ta cũng đã giải quyết xong xuôi các vấn đề tài chính, tuyển một Counter mới và thậm chí là có sự trở lại của người nữa,"
L32_1.m_Talk_VTN = L33_1
L33_1 = "总之资金问题已经解决了，又有了新的制裁者，而且老师也回来了。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Wie auch immer, wir haben unsere finanziellen Probleme gelöst, einen neuen Counter eingestellt und sogar dich zurückbekommen."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Quoi qu'il en soit, maintenant que nos soucis financiers sont derrière nous, que nous avons recruté une nouvelle Compteuse et que nous vous avons récupérée..."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "EP1_ACT1_STAGE4_END@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 14
L33_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L33_1.m_Pos = "L"
L34_1 = "올해는 좋은 결과를 기대해 볼 수 있을 것 같군요."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "今年は良い結果を期待できそうですね。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "I think we can look forward to a very good year."
L33_1.m_Talk_ENG = L34_1
L34_1 = "看來今年公司的情況會有所好轉。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ฉันคิดว่าปีนี้จะต้องเป็นปีที่ยอดเยี่ยมแน่ๆ เลยล่ะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Tôi nghĩ là chúng ta có thể mong chờ một năm vô cùng tốt."
L33_1.m_Talk_VTN = L34_1
L34_1 = "看来今年公司的情况会有所好转！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ich denke, wir können uns auf ein sehr gutes Jahr freuen."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Je pense que nous pouvons nous attendre à une très bonne année."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP1_ACT1_STAGE4_END@184#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 184
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 14
L34_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L34_1.m_Pos = "L"
L35_1 = "아 참. 그리고 스승님."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "あ、そうだ。師匠。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Oh, right. Master."
L34_1.m_Talk_ENG = L35_1
L35_1 = "啊，對了，師父。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เอ้อ อาจารย์คะ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Ồ đúng rồi. Sếp."
L34_1.m_Talk_VTN = L35_1
L35_1 = "啊，对了，老师。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Ach ja, noch etwas, Meisterin …"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Ah, j'oubliais. Maître."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP1_ACT1_STAGE4_END@185#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 14
L35_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L35_1.m_Pos = "R"
L36_1 = "또 왜?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "なんだ？"
L35_1.m_Talk_JPN = L36_1
L36_1 = "What now?"
L35_1.m_Talk_ENG = L36_1
L36_1 = "又怎麼了？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "มีอะไรอีกล่ะ?"
L35_1.m_Talk_THA = L36_1
L36_1 = "Giờ là chuyện gì nữa thế?"
L35_1.m_Talk_VTN = L36_1
L36_1 = "又怎么了？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Was denn noch?"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Quoi encore ?"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP1_ACT1_STAGE4_END@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 14
L36_1.m_CutScenStrID = "EP1_ACT1_STAGE4_END"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L36_1.m_Pos = "L"
L37_1 = "노파심에서 드리는 말씀이지만....... "
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "念のため言っておきますが…… 。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "I'm only saying this out of concern for you but... "
L36_1.m_Talk_ENG = L37_1
L37_1 = "以防萬一所以提前說一聲。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ฉันก็แค่อยากเตือนด้วยความเป็นห่วงน่ะค่ะ แต่ว่า... "
L36_1.m_Talk_THA = L37_1
L37_1 = "Tôi chỉ nói điều này vì lo lắng cho người nhưng... "
L36_1.m_Talk_VTN = L37_1
L37_1 = "以防万一所以提前说一下，"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ich sage das nur aus Sorge um dich, aber … "
L36_1.m_Talk_DEU = L37_1
L37_1 = "Je vous dis ça parce que je tiens à vous, mais... "
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
