L3_1 = "아까는 그동안 어디 있었냐고 잔소리더니."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "さっきはどこにいたんだと咎めていたくせに。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Two seconds ago, you were barking at me about where I was this whole time."
L2_1.m_Talk_ENG = L3_1
L3_1 = "妳剛剛不是還嘮嘮叨叨地，問我這段時間去哪裡了嗎？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "สองวินาทีที่แล้วเธอยังด่าฉันฉอดๆ อยู่เลย ว่าหายหัวไปไหน"
L2_1.m_Talk_THA = L3_1
L3_1 = "Hai giây trước, cô vẫn còn đang lải nhải với ta về nơi mà ta đã ở trong suốt khoảng thời gian này đấy."
L2_1.m_Talk_VTN = L3_1
L3_1 = "你刚刚不还唠唠叨叨地问我这段时间去哪儿了吗？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Gerade eben hast du mich noch heruntergeputzt, weil ich verschwunden war."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Il n'y a pas une minute vous étiez en train de m'aboyer dessus pour vous avoir abandonnés pendant tout ce temps."
L2_1.m_Talk_FRA = L3_1
