L6_1 = "전 스승님이 영원히 돌아오지 않을 거라고 생각했어요."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "私は師匠が永遠に戻ってこないと思っていました。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "I thought you were never coming back."
L5_1.m_Talk_ENG = L6_1
L6_1 = "我以為師父永遠不會回來了。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ฉันนึกว่าคุณจะไม่มีวันกลับมาอีกแล้ว"
L5_1.m_Talk_THA = L6_1
L6_1 = "Tôi tưởng là người sẽ không bao giờ quay lại nữa."
L5_1.m_Talk_VTN = L6_1
L6_1 = "我以为老师永远也不会回来了。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Ich dachte, du würdest nie zurückkommen."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Je pensais que vous ne reviendriez jamais."
L5_1.m_Talk_FRA = L6_1
