L6_1.m_Talk_THA = L7_1
L7_1 = "Tôi thậm chí còn nghĩ rằng có lẽ việc đó sẽ tốt hơn cho tất cả chúng ta."
L6_1.m_Talk_VTN = L7_1
L7_1 = "我那时想，也许老师不回来会更好。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Und ich dachte sogar, dass es vielleicht besser für uns alle wäre."
L6_1.m_Talk_DEU = L7_1
L7_1 = "J'ai même pensé à un moment que c'était peut-être mieux pour nous tous."
L6_1.m_Talk_FRA = L7_1
